/* prog20_anagram_checker.c
 *
 * Re‑implementation of the original anagram‑checking binary.
 * The program expects two strings as command‑line arguments.
 *
 *   $ ./prog20_anagram_checker <string1> <string2>
 *
 * Output (via puts, i.e. with a trailing newline):
 *   USAGE        – when fewer than two arguments are supplied
 *   TOO_LONG     – when either argument is 1024 characters or longer
 *   ANAGRAM      – when the two strings are anagrams (case‑insensitive,
 *                  spaces are ignored, only letters A‑Z/a‑z are considered)
 *   NOT_ANAGRAM  – otherwise
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LEN 1024   /* 0x401 bytes total, strings must be < 1024 chars */

int main(int argc, char *argv[])
{
    /* --------------------------------------------------------------------
     * Argument count check – the original binary prints "USAGE" when
     * argc < 3 (program name + two strings).  Extra arguments are ignored.
     * -------------------------------------------------------------------- */
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *s1 = argv[1];
    const char *s2 = argv[2];

    /* --------------------------------------------------------------------
     * Length check – the original code rejects strings of length >= 1024.
     * -------------------------------------------------------------------- */
    if (strlen(s1) >= MAX_LEN || strlen(s2) >= MAX_LEN) {
        puts("TOO_LONG");
        return 0;
    }

    /* --------------------------------------------------------------------
     * Count letters of the first string (case‑insensitive, ignore spaces).
     * The original binary used two 0x400‑byte arrays indexed by the byte
     * value; we can safely use a 256‑element array.
     * -------------------------------------------------------------------- */
    int cnt[256] = {0};

    for (size_t i = 0; s1[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)s1[i];
        if (c == ' ')               /* spaces are ignored */
            continue;
        if (isalpha(c)) {
            c = (unsigned char)tolower(c);
            cnt[c]++;               /* increment count for this letter */
        }
    }

    /* --------------------------------------------------------------------
     * Process the second string: decrement the same counters.
     * -------------------------------------------------------------------- */
    for (size_t i = 0; s2[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)s2[i];
        if (c == ' ')
            continue;
        if (isalpha(c)) {
            c = (unsigned char)tolower(c);
            cnt[c]--;               /* decrement count for this letter */
        }
    }

    /* --------------------------------------------------------------------
     * Determine whether all counters are zero – that means the two strings
     * contain exactly the same multiset of letters (ignoring case and spaces).
     * -------------------------------------------------------------------- */
    int is_anagram = 1;
    for (int i = 0; i < 256; ++i) {
        if (cnt[i] != 0) {
            is_anagram = 0;
            break;
        }
    }

    puts(is_anagram ? "ANAGRAM" : "NOT_ANAGRAM");
    return 0;
}
